-- new draft set versions pointing at the E1019-M*/P* patched problem versions(a set with an existing draft is skipped - publish/discard it first)
-- generated by scripts/prod-open/sat-expand-sql.ts (SAT_11=1). Run: npx supabase db query --linked -f <this file>. Idempotent; drafts only (never published here); published sets/attempts untouched.

do $os$
declare
  v_sp constant jsonb := $satx${"name":"SAT Practice Test 1","repointProblemIds":["4cc47e7c-e766-47d8-aa9b-ae16aeb96d71","05fcc748-6621-41c8-871c-a1bd9ac131eb","079d2fb7-55f3-455f-a32c-32b252e0da59","0b94e63d-1d30-4fdb-ad23-2ea8895e0978","1473eff6-7ef8-48a6-add7-d241754fdec6","2c4d3a89-40e8-4de9-9d80-7d91657c2674","508b24dd-fe8e-43c6-b165-408aac130a64","01d7207e-c5d8-4b93-a2ea-ba5b57b7ff0e","457a2e9f-02ef-41d4-b1d3-a6f1e6e6d90d"],"slots":[]}$satx$::jsonb;
  v_actor uuid := (select id from profiles where role = 'admin' order by created_at limit 1); v_src mock_exam_sets%rowtype; v_new uuid := gen_random_uuid(); v_cols text; v_cols_i text; v_pids uuid[]; sl jsonb; v_npid uuid; v_p problems%rowtype; v_stale int; v_slots int := 0; v_bad text; v_slotsj jsonb := '[]'::jsonb;
begin
  begin
    select * into v_src from mock_exam_sets where name = v_sp->>'name' and status = 'published' and archived_at is null for update;
    if v_src.id is null then raise exception 'published % not found', v_sp->>'name'; end if;
    select array_agg(x::uuid) into v_pids from jsonb_array_elements_text(v_sp->'repointProblemIds') x;
    v_pids := coalesce(v_pids, array[]::uuid[]);
    select count(*) into v_stale from mock_exam_set_items i join problems p on p.id = i.problem_id where i.exam_set_id = v_src.id and i.problem_id = any (v_pids) and p.published_version_id is distinct from i.problem_version_id;
    for sl in select * from jsonb_array_elements(v_sp->'slots') loop
      if exists (select 1 from mock_exam_set_items i where i.exam_set_id = v_src.id and i.section = sl->>'section' and i.position = (sl->>'position')::int and i.problem_version_id = (sl->>'oldVersionId')::uuid) then v_slots := v_slots + 1; end if;
    end loop;
    if v_stale = 0 and v_slots = 0 then raise notice '% nothing to change (already up to date) - skipped', v_src.name; return; end if;
    if exists (select 1 from mock_exam_sets where set_group_id = v_src.set_group_id and status = 'draft') then raise notice '% a draft version already exists - skipped (publish/discard it, then re-run)', v_src.name; return; end if;
    perform pg_advisory_xact_lock(hashtextextended('mock_exam_new_version:' || v_src.set_group_id::text, 0));
    select string_agg(quote_ident(column_name), ', ' order by ordinal_position) into v_cols from information_schema.columns where table_schema = 'public' and table_name = 'mock_exam_sets' and is_generated = 'NEVER' and column_name not in ('id', 'version_no', 'status', 'created_by', 'created_at', 'published_at', 'published_by', 'archived_at', 'access_tier', 'readiness_status', 'readiness_report', 'readiness_checked_at');
    execute format('insert into mock_exam_sets (id, version_no, status, created_by, access_tier, %s) select $1, $2, ''draft'', $3, ''tutoring'', %s from mock_exam_sets where id = $4', v_cols, v_cols)
      using v_new, (select max(version_no) + 1 from mock_exam_sets where set_group_id = v_src.set_group_id), v_actor, v_src.id;
    -- 교체 칸 목록(이 세트에서 아직 옛 문항인 칸만)
    for sl in select * from jsonb_array_elements(v_sp->'slots') loop
      if exists (select 1 from mock_exam_set_items i where i.exam_set_id = v_src.id and i.section = sl->>'section' and i.position = (sl->>'position')::int and i.problem_version_id = (sl->>'oldVersionId')::uuid) then v_slotsj := v_slotsj || jsonb_build_array(sl); end if;
    end loop;
    select string_agg(quote_ident(column_name), ', ' order by ordinal_position),
           string_agg(case column_name when 'problem_version_id' then 'case when i.problem_id = any ($3) then coalesce(p.published_version_id, i.problem_version_id) else i.problem_version_id end'
                                       when 'content_snapshot' then 'case when i.problem_id = any ($3) then null else i.content_snapshot end' else 'i.' || quote_ident(column_name) end, ', ' order by ordinal_position)
      into v_cols, v_cols_i from information_schema.columns where table_schema = 'public' and table_name = 'mock_exam_set_items' and is_generated = 'NEVER' and column_name not in ('id', 'exam_set_id', 'created_at');
    execute format('insert into mock_exam_set_items (exam_set_id, %s) select $1, %s from mock_exam_set_items i join problems p on p.id = i.problem_id where i.exam_set_id = $2
                    and not exists (select 1 from jsonb_to_recordset($4) as x(section text, position int) where x.section = i.section and x.position = i.position)', v_cols, v_cols_i) using v_new, v_src.id, v_pids, v_slotsj;
    for sl in select * from jsonb_array_elements(v_slotsj) loop
      v_npid := coalesce((sl->>'newProblemId')::uuid, (select problem_id from problem_versions where quality->'mockExamGeneration'->>'gid' = sl->>'newGid' limit 1));
      select * into v_p from problems where id = v_npid;
      if v_p.id is null or v_p.status <> 'confirmed' or v_p.archived_at is not null or v_p.published_version_id is null then raise exception 'replacement for slot %/% not usable (%)', sl->>'section', sl->>'position', coalesce(sl->>'newGid', sl->>'newProblemId'); end if;
      if exists (select 1 from mock_exam_set_items x where x.problem_id = v_npid and x.exam_set_id in (select id from mock_exam_sets where archived_at is null and status <> 'archived' and id <> v_new)) then raise exception 'replacement % already used in another live set', v_npid; end if;
      insert into mock_exam_set_items (exam_set_id, section, position, problem_id, problem_version_id, sat_domain, skill_code, difficulty, module_key, route)
      select v_new, i.section, i.position, v_npid, v_p.published_version_id, i.sat_domain, i.skill_code, i.difficulty, i.module_key, i.route from mock_exam_set_items i where i.exam_set_id = v_src.id and i.section = sl->>'section' and i.position = (sl->>'position')::int;
    end loop;
    if not coalesce((public.mock_exam_validate_mst_set(v_new)->>'ready')::boolean, false) then raise exception 'old set new version: 4-module/rule validation failed %', public.mock_exam_validate_mst_set(v_new)::text; end if;
    select string_agg(x.problem_id::text || ':' || x.issue, ', ') into v_bad from (select * from public.mock_exam_set_item_issues(v_new) where issue is not null limit 5) x;
    if v_bad is not null then raise exception 'old set new version: item issues %', v_bad; end if;
    update mock_exam_sets set readiness_status = 'ready', readiness_report = public.mock_exam_validate_mst_set(v_new) || jsonb_build_object('shortfalls', '[]'::jsonb, 'checkedAt', now()), readiness_checked_at = now() where id = v_new;
    raise notice '% new draft version created (% repointed items, % replaced slots) -> %', v_src.name, v_stale, v_slots, v_new;
  exception when others then raise notice '% SKIPPED: %', v_sp->>'name', sqlerrm;
  end;
end
$os$;

